"""
rail_predict.py : bearing fault prediction, all in one file.

Usage (from a terminal):
    python rail_predict.py <folder_with_csv_files> [output_csv]

Example:
    python rail_predict.py data\\test
    -> writes rail_predictions.csv with columns file_id,prediction

Every .csv file in the folder is treated as a test file and gets exactly one
row. The trained model is embedded at the bottom of this file, so no other
files are needed. Requires: numpy, pandas, scikit-learn, joblib
(scikit-learn should be the same version the model was trained with).
"""

import base64
import io
import re
import sys
import warnings
from pathlib import Path

import joblib
import numpy as np
import pandas as pd
from sklearn.base import BaseEstimator, TransformerMixin

warnings.filterwarnings("ignore")

OUTPUT_FILE = "rail_predictions.csv"

# ----------------------------------------------------------------------------
# FEATURE SETTINGS (must match training)
# ----------------------------------------------------------------------------
SIDE_1 = [1, 3, 5, 7]
SIDE_2 = [2, 4, 6, 8]
HALF_A = [1, 2, 3, 4]
HALF_B = [5, 6, 7, 8]
PCT = 99
N_WINDOWS = 10
EPS = 1e-9
SEP = "|"
COL_RE = re.compile(r"(Vibration|Shock) of bearing in position (\d+) of car (\d+)", re.I)
LOG_STATS = ["rms", "std", f"p{PCT}", "crest", "kurt", "hf", "lf"]
SIGNED_STATS = ["mean"]
RAW_SIDE_STATS = {"vibration": ["rms", "std", f"p{PCT}"], "shock": ["mean", "std", f"p{PCT}"]}
SKIP_STATS = {("shock", "hf"), ("shock", "lf")}


# ----------------------------------------------------------------------------
# STEP 1: raw file -> per-bearing measurements
# ----------------------------------------------------------------------------
def to_arrays(df):
    pulse = df.iloc[:, 0].to_numpy()
    parsed = []
    for c in df.columns:
        m = COL_RE.fullmatch(str(c).strip())
        if m:
            parsed.append((c, m.group(1).lower(), int(m.group(2)), int(m.group(3))))
    cars = sorted({car for *_, car in parsed})
    positions = sorted({pos for _, _, pos, _ in parsed})
    arrays = {}
    for sig in ["vibration", "shock"]:
        a = np.full((len(df), len(cars), len(positions)), np.nan)
        for col, s, pos, car in parsed:
            if s == sig:
                a[:, cars.index(car), positions.index(pos)] = df[col].to_numpy()
        arrays[sig] = np.nan_to_num(a)
    return pulse, arrays, cars, positions


def speed_features(pulse):
    flips = np.flatnonzero(np.diff(pulse) != 0)
    runs = np.diff(flips)
    return {
        "speed|rate": (len(flips) + 0.5) / len(pulse) * 1000,
        "speed|log_rate": np.log((len(flips) + 0.5) / len(pulse)),
        "speed|regularity": float(runs.std() / runs.mean()) if len(runs) > 2 else 0.0,
    }


def bearing_stats(x):
    c = x - x.mean(axis=0)
    var = (c ** 2).mean(axis=0) + EPS
    rms = np.sqrt((x ** 2).mean(axis=0)) + EPS
    p = np.percentile(np.abs(x), PCT, axis=0) + EPS
    spec = (np.abs(np.fft.rfft(c, axis=0)) ** 2)[1:]
    f = np.linspace(0, 1, spec.shape[0])[:, None, None]
    total = spec.sum(axis=0) + EPS
    return {
        "rms": np.log(rms),
        "std": np.log(np.sqrt(var)),
        f"p{PCT}": np.log(p),
        "crest": np.log(p / rms),
        "kurt": np.log((c ** 4).mean(axis=0) / var ** 2 + 0.1),
        "hf": np.log((spec * (f > 0.5)).sum(axis=0) / total + 1e-4),
        "lf": np.log((spec * (f < 0.1)).sum(axis=0) / total + 1e-4),
        "mean": x.mean(axis=0),
    }


def group_features(pulse, arrays, cars, positions):
    f = dict(speed_features(pulse))
    i1 = [positions.index(p) for p in SIDE_1]
    i2 = [positions.index(p) for p in SIDE_2]
    for sig, a in arrays.items():
        for stat, m in bearing_stats(a).items():
            if (sig, stat) in SKIP_STATS:
                continue
            for ci, car in enumerate(cars):
                for pi, pos in enumerate(positions):
                    f[SEP.join([sig, stat, f"c{car}", f"p{pos}"])] = m[ci, pi]
        z = (a - a.mean(0)) / (a.std(0) + EPS)
        pc = (z[:, :, i1] * z[:, :, i2]).mean(axis=0)
        for ci, car in enumerate(cars):
            for ax in range(len(i1)):
                f[SEP.join([sig, "paircorr", f"c{car}", f"a{ax + 1}"])] = pc[ci, ax]
        n_win = max(1, min(N_WINDOWS, len(a) // 200))
        for w, block in enumerate(np.array_split(a, n_win)):
            lr = np.log(np.sqrt((block ** 2).mean(0)) + EPS)
            lr = lr - np.median(lr)
            asym = lr[:, i1].mean(1) - lr[:, i2].mean(1)
            for ci, car in enumerate(cars):
                f[SEP.join([sig, "winasym", f"c{car}", f"w{w}"])] = asym[ci]
    return f


# ----------------------------------------------------------------------------
# STEP 2: comparison features (this class is part of the saved model)
# ----------------------------------------------------------------------------
def feature_group(name):
    if name.startswith("speed" + SEP):
        return "speed"
    if "_speedadj" in name:
        return "levels"
    if name.endswith(("_side1_avg", "_side2_avg", "_side_diff", "_side_ratio", "_overall_z")):
        return "raw"
    if "_win_" in name or "persist" in name or "consistency" in name:
        return "window"
    if "paircorr" in name:
        return "pair"
    return "asym"


class FaultFeatures(BaseEstimator, TransformerMixin):
    """Transform-only copy of the training class; the fitted values come from the model."""

    def __init__(self, normal_label="Normal", z_clip=10.0, z_flag=3.0, persist_z=2.0,
                 groups=None):
        self.groups = groups
        self.normal_label = normal_label
        self.z_clip = z_clip
        self.z_flag = z_flag
        self.persist_z = persist_z

    def fit(self, X, y=None):
        raise NotImplementedError("This file only predicts. Train with train_model.py.")

    def _arrays(self, X, sig, stat):
        c1, c2 = self.bear_[(sig, stat)]
        n, nc = len(X), len(self.cars_)
        a1 = X[c1].to_numpy(float).reshape(n, nc, -1)
        a2 = X[c2].to_numpy(float).reshape(n, nc, -1)
        return a1, a2

    def _relative(self, a1, a2, stat):
        if stat in SIGNED_STATS:
            return a1, a2
        lvl = np.median(np.concatenate([a1, a2], axis=2), axis=(1, 2))[:, None, None]
        return a1 - lvl, a2 - lvl

    def _levels(self, X):
        cols, names = [], []
        pos_all = SIDE_1 + SIDE_2
        order = np.argsort(pos_all)
        for (sig, stat) in self.bear_:
            a1, a2 = self._arrays(X, sig, stat)
            a = np.concatenate([a1, a2], axis=2)[:, :, order]
            p = {pos: a[:, :, i] for i, pos in enumerate(sorted(pos_all))}
            tag = f"{sig}_{stat}"
            groups = {"all": sorted(pos_all), "side1": SIDE_1, "side2": SIDE_2,
                      "half14": HALF_A, "half58": HALF_B}
            for g, members in groups.items():
                cols.append(np.mean([p[m] for m in members], axis=0).mean(1))
                names.append(f"{tag}_lvl_{g}")
            for pos in sorted(pos_all):
                cols.append(p[pos].mean(1))
                names.append(f"{tag}_lvl_pos{pos}")
            for ci, car in enumerate(self.cars_):
                cols.append(a[:, ci, :].mean(1))
                names.append(f"{tag}_lvl_car{car}")
        return np.column_stack(cols), names

    def _speed_design(self, X):
        if "speed|rate" in X:
            r = X["speed|rate"].to_numpy(float) / 100.0
        else:
            r = np.zeros(len(X))
        return np.column_stack([np.ones_like(r), r, r ** 2])

    def _level_features(self, X):
        L, names = self._levels(X)
        resid = L - self._speed_design(X) @ self.level_coef_
        Z = self._z(resid, self.level_center_, self.level_scale_)
        out = {f"{nm}_speedadj_z": Z[:, j] for j, nm in enumerate(names)}
        idx = {nm: j for j, nm in enumerate(names)}
        for (sig, stat) in self.bear_:
            t = f"{sig}_{stat}"
            out[f"{t}_speedadj_side_diff"] = Z[:, idx[f"{t}_lvl_side1"]] - Z[:, idx[f"{t}_lvl_side2"]]
            out[f"{t}_speedadj_half_diff"] = Z[:, idx[f"{t}_lvl_half14"]] - Z[:, idx[f"{t}_lvl_half58"]]
            cars = Z[:, [idx[f"{t}_lvl_car{c}"] for c in self.cars_]]
            out[f"{t}_speedadj_car_max"] = cars.max(1)
            out[f"{t}_speedadj_car_min"] = cars.min(1)
        return out

    def _z(self, a, med, scale):
        return np.clip((a - med) / scale, -self.z_clip, self.z_clip)

    def transform(self, X):
        X = pd.DataFrame(X).reindex(columns=self.columns_).fillna(self.fill_)
        n = len(X)
        out = {c: X[c].to_numpy(float) for c in self.speed_cols_}
        out.update(self._level_features(X))

        for (sig, stat), _ in self.bear_.items():
            name = f"{sig}_{stat}"
            raw1, raw2 = self._arrays(X, sig, stat)
            a1, a2 = self._relative(raw1, raw2, stat)
            (m1, s1), (m2, s2) = self.base_[(sig, stat)]
            z1, z2 = self._z(a1, m1, s1), self._z(a2, m2, s2)

            car = z1.mean(2) - z2.mean(2)
            out[f"{name}_car_asym_max"] = car.max(1)
            out[f"{name}_car_asym_min"] = car.min(1)
            out[f"{name}_car_asym_mean"] = car.mean(1)
            out[f"{name}_car_asym_spread"] = car.std(1)

            ax = (z1 - z2).reshape(n, -1)
            srt = np.sort(ax, 1)
            out[f"{name}_axle_asym_max"] = srt[:, -1]
            out[f"{name}_axle_asym_min"] = srt[:, 0]
            out[f"{name}_axle_asym_top3"] = srt[:, -3:].mean(1)
            out[f"{name}_axle_asym_bot3"] = srt[:, :3].mean(1)

            out[f"{name}_side1_z"] = z1.mean((1, 2))
            out[f"{name}_side2_z"] = z2.mean((1, 2))
            out[f"{name}_side1_zmax"] = np.abs(z1).reshape(n, -1).max(1)
            out[f"{name}_side2_zmax"] = np.abs(z2).reshape(n, -1).max(1)
            out[f"{name}_side1_n_unusual"] = (np.abs(z1) > self.z_flag).reshape(n, -1).sum(1)
            out[f"{name}_side2_n_unusual"] = (np.abs(z2) > self.z_flag).reshape(n, -1).sum(1)

            if (sig, stat, "level") in self.base_:
                lvl = np.concatenate([raw1, raw2], axis=2).mean(axis=(1, 2))
                m, s = self.base_[(sig, stat, "level")]
                out[f"{name}_overall_z"] = self._z(lvl, m, s)

            if stat in RAW_SIDE_STATS.get(sig, []):
                v1 = raw1 if stat in SIGNED_STATS else np.exp(raw1)
                v2 = raw2 if stat in SIGNED_STATS else np.exp(raw2)
                sa, sb = v1.mean((1, 2)), v2.mean((1, 2))
                out[f"{name}_side1_avg"] = sa
                out[f"{name}_side2_avg"] = sb
                out[f"{name}_side_diff"] = sa - sb
                if stat not in SIGNED_STATS:
                    out[f"{name}_side_ratio"] = sa / (sb + EPS)

        for sig in self.sigs_:
            m, s = self.base_[(sig, "pair")]
            zp = self._z(X[self.pair_[sig]].to_numpy(float), m, s)
            out[f"{sig}_paircorr_min"] = zp.min(1)
            out[f"{sig}_paircorr_mean"] = zp.mean(1)
            if self.n_win_:
                m, s = self.base_[(sig, "win")]
                w = X[self.win_[sig]].to_numpy(float).reshape(n, len(self.cars_), -1)
                zw = self._z(w, m[None, :, None], s[None, :, None])
                med_w = np.median(zw, 2)
                out[f"{sig}_win_asym_median_max"] = med_w.max(1)
                out[f"{sig}_win_asym_median_min"] = med_w.min(1)
                out[f"{sig}_persist_side1"] = (zw > self.persist_z).mean(2).max(1)
                out[f"{sig}_persist_side2"] = (zw < -self.persist_z).mean(2).max(1)
                out[f"{sig}_consistency"] = np.abs(np.sign(zw).mean(2)).max(1)

        out = pd.DataFrame(out, index=X.index).fillna(0)
        if self.groups is not None:
            out = out[[c for c in out.columns if feature_group(c) in self.groups]]
        return out

    def get_feature_names_out(self, input_features=None):
        return np.array(self.feature_names_out_)


# ----------------------------------------------------------------------------
# STEP 3: load the embedded model and predict a whole folder
# ----------------------------------------------------------------------------
def load_model():
    # The model was saved while FaultFeatures lived in extract_features.py;
    # point that name at this file so the model finds the class here.
    sys.modules["extract_features"] = sys.modules[__name__]
    return joblib.load(io.BytesIO(base64.b64decode(MODEL_B64)))


def natural_key(p):
    return [int(t) if t.isdigit() else t.lower() for t in re.split(r"(\d+)", p.name)]


def main():
    if len(sys.argv) < 2:
        raise SystemExit("Usage: python rail_predict.py <folder_with_csv_files> [output_csv]")
    folder = Path(sys.argv[1])
    output = Path(sys.argv[2]) if len(sys.argv) > 2 else Path(OUTPUT_FILE)

    files = sorted((p for p in folder.glob("*.csv")
                    if p.resolve() != output.resolve() and not p.name.startswith("~$")),
                    key=natural_key)
    if not files:
        raise SystemExit(f"No .csv files found in {folder}")

    bundle = load_model()
    model = bundle["model"]
    base_features = bundle["base_features"]
    boost = bundle.get("fault_boost", 1.0)
    normal = bundle.get("normal_label", "Normal")
    classes = list(model.classes_)
    weights = np.array([1.0 if c == normal else boost for c in classes])

    rows = [group_features(*to_arrays(pd.read_csv(p))) for p in files]
    X = pd.DataFrame(rows).reindex(columns=base_features)
    proba = model.predict_proba(X)
    preds = [classes[i] for i in np.argmax(proba * weights, axis=1)]

    pd.DataFrame({"file_id": [p.name for p in files], "prediction": preds}) \
        .to_csv(output, index=False)
    print(f"Saved {output} ({len(files)} files)")


